import subprocess, os, re
def run_raw(args, env=None):
    import subprocess as sp
    e = {}
    if env:
        e.update(env)
    e["PATH"]=os.environ.get("PATH","/usr/bin:/bin")
    r = sp.run(["./executable"]+args, capture_output=True, env=e)
    return r.stdout, r.stderr, r.returncode

def get_gray(color_name):
    out,_,_ = run_raw([f"/tmp/solid_{color_name}.png","-d","1,1","--grayscale"], env={"COLORTERM":"truecolor"})
    # parse \x1b[38;2;R;G;Bm
    m=re.search(rb"38;2;(\d+);(\d+);(\d+)m", out)
    if m:
        return tuple(map(int,m.groups()))
    return out

for c in ["red","green","blue","black","white"]:
    print(c, get_gray(c))

