import subprocess, os
def run_full(args, env=None):
    import subprocess as sp
    e = {}
    if env:
        e.update(env)
    e["PATH"]=os.environ.get("PATH","/usr/bin:/bin")
    r = sp.run(["./executable"]+args, capture_output=True, env=e)
    return r.stdout

def unpack(ch):
    code = ord(ch) - 0x2800
    bits = [(code>>i)&1 for i in range(8)]
    grid = [[0]*2 for _ in range(4)]
    grid[0][0]=bits[0]
    grid[1][0]=bits[1]
    grid[2][0]=bits[2]
    grid[0][1]=bits[3]
    grid[1][1]=bits[4]
    grid[2][1]=bits[5]
    grid[3][0]=bits[6]
    grid[3][1]=bits[7]
    return grid

def show(path, dims):
    out=run_full([path,"-d",dims,"--braille","--dither"], env={})
    s=out.decode('utf-8').strip().split("\n")
    W,H=map(int,dims.split(","))
    img=[[0]*(W*2) for _ in range(H*4)]
    for by, row in enumerate(s):
        for bx, ch in enumerate(row):
            g=unpack(ch)
            for dy in range(4):
                for dx in range(2):
                    img[by*4+dy][bx*2+dx]=g[dy][dx]
    print(f"{path} {dims} dither:")
    for row in img:
        print(''.join('#' if v else '.' for v in row))
    print(f"braille hex: {[hex(ord(c)) for row in s for c in row]}")
    print()

