package main

import (
	"fmt"
	"strconv"
	"strings"
)

type FlagValues struct {
	Color      bool
	ColorBg    bool
	Dimensions []int
	Width      int
	WidthSet   bool
	Height     int
	HeightSet  bool
	Map        string
	Braille    bool
	Threshold  int
	ThresholdSet bool
	Dither     bool
