	SaveGif    string
	SaveBg     []int
	Font       string
	FontColor  []int
	OnlySave   bool
	Formats    bool
	Help       bool
	Version    bool
}

func defaultFlags() *FlagValues {
	return &FlagValues{
		Threshold: 128,
	}
}

// Flag metadata for error messages
type flagInfo struct {
	long      string
	short     string // single char or ""
	typ       string // "bool", "int", "string", "ints"
}

var allFlags = []flagInfo{
	{"color", "C", "bool"},
	{"color-bg", "", "bool"},
	{"dimensions", "d", "ints"},
	{"width", "W", "int"},
	{"height", "H", "int"},
	{"map", "m", "string"},
	{"braille", "b", "bool"},
	{"threshold", "", "int"},
	{"dither", "", "bool"},
	{"grayscale", "g", "bool"},
	{"complex", "c", "bool"},
	{"full", "f", "bool"},
	{"negative", "n", "bool"},
	{"flipX", "x", "bool"},
	{"flipY", "y", "bool"},
	{"save-img", "s", "string"},
	{"save-txt", "", "string"},
	{"save-gif", "", "string"},
	{"save-bg", "", "ints"},
	{"font", "", "string"},
	{"font-color", "", "ints"},
	{"only-save", "", "bool"},
	{"formats", "", "bool"},
	{"help", "h", "bool"},
	{"version", "v", "bool"},
}

func findLong(name string) *flagInfo {
	for i := range allFlags {
		if allFlags[i].long == name {
			return &allFlags[i]
		}
	}
	return nil
}
func findShort(ch string) *flagInfo {
	for i := range allFlags {
		if allFlags[i].short == ch {
			return &allFlags[i]
		}
	}
	return nil
}

func flagDisplayName(fi *flagInfo) string {
	if fi.short != "" {
		return fmt.Sprintf("\"-%s, --%s\"", fi.short, fi.long)
	}
	return fmt.Sprintf("\"--%s\"", fi.long)
}

// Parse error to be printed to stdout (without Error: prefix) and stderr (with Error: + usage)
type parseError struct {
	msg string
}

func (e *parseError) Error() string { return e.msg }

func parseBoolVal(s string, fi *flagInfo) (bool, error) {
	b, err := strconv.ParseBool(s)
	if err != nil {
		return false, &parseError{msg: fmt.Sprintf("invalid argument %q for %s flag: %s", s, flagDisplayName(fi), err.Error())}
	}
	return b, nil
}
func parseIntVal(s string, fi *flagInfo) (int, error) {
	// pflag uses ParseInt with 0 base? Actually strconv.ParseInt(s, 0, 64)? For decimal, same as Atoi but error message differs: ParseInt vs Atoi?
	// For int flags, error is "strconv.ParseInt: parsing ...", for ints slice, "strconv.Atoi: ..."
	// Use ParseInt to match message
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		return 0, &parseError{msg: fmt.Sprintf("invalid argument %q for %s flag: %s", s, flagDisplayName(fi), err.Error())}
	}
	return int(v), nil
}
func parseIntsVal(s string, fi *flagInfo) ([]int, error) {
	// Split by comma, parse each with Atoi
	if s == "" {
		// For --flag= (empty), pflag gives invalid argument "" with Atoi parsing ""?
		// Observed: --font-color= (empty) gives invalid argument "" with Atoi parsing ""
		_, err := strconv.Atoi("")
		// err is "strconv.Atoi: parsing \"\": invalid syntax"
		return nil, &parseError{msg: fmt.Sprintf("invalid argument %q for %s flag: %s", s, flagDisplayName(fi), err.Error())}
	}
	parts := strings.Split(s, ",")
	var res []int
	for _, p := range parts {
		v, err := strconv.Atoi(p)
		if err != nil {
			return nil, &parseError{msg: fmt.Sprintf("invalid argument %q for %s flag: %s", s, flagDisplayName(fi), err.Error())}
		}
		res = append(res, v)
	}
	return res, nil
}

func parseArgs(args []string) (*FlagValues, []string, error) {
	fv := defaultFlags()
	var positional []string
	i := 0
	endOfFlags := false
	for i < len(args) {
		arg := args[i]
		if endOfFlags {
			positional = append(positional, arg)
			i++
			continue
		}
		if arg == "--" {
			endOfFlags = true
			i++
			continue
		}
		if arg == "-" {
			positional = append(positional, arg)
			i++
			continue
		}
		if strings.HasPrefix(arg, "--") {
			// Long flag
			eqIdx := strings.Index(arg, "=")
			var name, val string
			var hasEq bool
			if eqIdx != -1 {
				name = arg[2:eqIdx]
				val = arg[eqIdx+1:]
				hasEq = true
