package main

import (
	"fmt"
	"os"
	"strings"
	_ "embed"
)

//go:embed help.txt
var helpText string

func getUsageForStderr() string {
	idx := strings.Index(helpText, "Usage:")
	if idx == -1 {
		return ""
	}
	usage := helpText[idx:]
	// stderr usage has extra newline at end (help ends with \n, stderr ends with \n\n)
	if !strings.HasSuffix(usage, "\n\n") {
		usage += "\n"
	}
	return usage
}

func printHelp() {
	fmt.Fprint(os.Stdout, helpText)
}
func printVersion() {
	fmt.Fprintln(os.Stdout, "v1.13.1")
}
func printFormats() {
	fmt.Fprint(os.Stdout, "Supported input formats:\n\nJPEG/JPG\nPNG\nWEBP\nBMP\nTIFF/TIF\nGIF\n\n")
}

func main() {
	fv, positional, err := parseArgs(os.Args[1:])
	if err != nil {
		// Flag parsing error: stdout <msg>\n, stderr Error: <msg>\n + usage
		msg := err.Error()
		fmt.Fprintln(os.Stdout, msg)
		fmt.Fprintf(os.Stderr, "Error: %s\n%s", msg, getUsageForStderr())
		os.Exit(1)
	}
