func decodeBMPData(data []byte) (image.Image, error) {
	if len(data) < 54 {
		return nil, errors.New("bmp: unsupported BMP image")
	}
	if data[0] != 'B' || data[1] != 'M' {
		return nil, errors.New("image: unknown format")
	}
	off := int(binary.LittleEndian.Uint32(data[10:14]))
	headerSize := int(binary.LittleEndian.Uint32(data[14:18]))
	if headerSize != 40 {
		return nil, errors.New("bmp: unsupported BMP image")
	}
	w := int(int32(binary.LittleEndian.Uint32(data[18:22])))
	h := int(int32(binary.LittleEndian.Uint32(data[22:26])))
	planes := int(binary.LittleEndian.Uint16(data[26:28]))
	bpp := int(binary.LittleEndian.Uint16(data[28:30]))
	compression := int(binary.LittleEndian.Uint32(data[30:34]))
	if planes != 1 || (bpp != 24 && bpp != 32) || compression != 0 {
		return nil, errors.New("bmp: unsupported BMP image")
	}
	if w <= 0 || h == 0 {
		return nil, errors.New("bmp: unsupported BMP image")
	}
	topDown := false
	if h < 0 {
		h = -h
		topDown = true
	}
	// Row size padded to 4 bytes
	var rowSize int
	if bpp == 24 {
		rowSize = ((w*3 + 3) / 4) * 4
	} else {
		rowSize = w * 4
	}
	if len(data) < off+rowSize*h {
		// Truncated? Return unexpected EOF? Original for truncated BMP? Not tested. Use unexpected EOF to match PNG/JPEG truncated?
		// For BMP truncated, x/image/bmp might return "unexpected EOF" or "bmp: ..."? Let's return unexpected EOF for short data.
		return nil, errors.New("unexpected EOF")
	}
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		var srcY int
		if topDown {
			srcY = y
		} else {
			srcY = h - 1 - y
		}
		rowOff := off + srcY*rowSize
		for x := 0; x < w; x++ {
			var r, g, b uint8
			if bpp == 24 {
				b = data[rowOff+x*3+0]
				g = data[rowOff+x*3+1]
				r = data[rowOff+x*3+2]
			} else {
				b = data[rowOff+x*4+0]
				g = data[rowOff+x*4+1]
				r = data[rowOff+x*4+2]
				// Alpha at +3 ignored (assume opaque)
			}
			img.SetRGBA(x, y, color.RGBA{r, g, b, 255})
		}
	}
	return img, nil
}

