			var typeSize int
			switch typ {
			case 1, 2:
				typeSize = 1
			case 3:
				typeSize = 2
			case 4:
				typeSize = 4
			case 5:
				typeSize = 8
			default:
				return nil, errors.New("image: unknown format")
			}
			total := typeSize * count
			var raw []byte
			if total <= 4 {
				raw = data[valOff : valOff+4]
			} else {
				ptr := int(order.Uint32(data[valOff : valOff+4]))
				if ptr+total > len(data) {
					return nil, errors.New("image: unknown format")
				}
				raw = data[ptr : ptr+total]
			}
			var vals []int
			for j := 0; j < count; j++ {
