				samplesPerPixel = vals[0]
			}
		case 278: // RowsPerStrip
			vals, _ := getVals()
			if len(vals) > 0 {
				rowsPerStrip = vals[0]
			}
		case 279: // StripByteCounts
			vals, _ := getVals()
			stripByteCounts = vals
		case 320: // ColorMap
