					if pos+1 > len(data) {
						return nil, errors.New("unexpected EOF")
					}
					idx := int(data[pos])
					pos++
					// ColorMap: R[0..2^N-1], G[0..], B[0..], each 0-65535, convert to 8-bit by >>8?
