func decodePackBits(src []byte) ([]byte, error) {
	var dst []byte
	i := 0
	for i < len(src) {
		n := int(int8(src[i]))
		i++
		if n >= 0 {
			// Copy next n+1 bytes
			if i+n+1 > len(src) {
				return nil, errors.New("unexpected EOF")
			}
			dst = append(dst, src[i:i+n+1]...)
			i += n + 1
		} else if n > -128 {
			// Replicate next byte -n+1 times
			if i >= len(src) {
				return nil, errors.New("unexpected EOF")
			}
			b := src[i]
			i++
			for j := 0; j < -n+1; j++ {
				dst = append(dst, b)
			}
		} else {
			// -128 noop
		}
	}
	return dst, nil
}

func decodeTIFFUncompressedFromBuffer(buf []byte, width, height int, bitsPerSample []int, photometric, samplesPerPixel int, colorMap []uint16) (image.Image, error) {
	if len(bitsPerSample) == 0 {
		if photometric == 2 {
