	if thresh == 0 {
		thresh = 128
	}
	// Build gray matrix
	grays := make([][]uint8, effH)
	for y := 0; y < effH; y++ {
		grays[y] = make([]uint8, effW)
		for x := 0; x < effW; x++ {
			c := color.RGBAModel.Convert(resized.At(b.Min.X+x, b.Min.Y+y)).(color.RGBA)
			g := grayValue(c.R, c.G, c.B)
			if fv.Negative {
				// For braille, negative inverts image before threshold? As observed, grad4 [0,85,170,255] negative => [255,170,85,0] threshold 128 => [full,full,blank,blank]? Actually grad4 braille negative gave [full,full,blank,blank] (inverted). Good. So invert gray.
				g = 255 - g
			}
			grays[y][x] = g
		}
	}
	var binary [][]int // 0/1 for each effective pixel (1=white/dot on)
	if fv.Dither {
		binary = ditherFloydLinear(grays, effW, effH)
		// Dither with negative? Negative already applied to grays before dither (invert). Good. What about dither threshold? Dither negates threshold (ignores thresh). Good. Our dither uses threshold 128 in linear? Actually dither threshold is fixed 128? Or 128 in linear? Our dither function uses threshold 128 in linear 0-255? Good.
	} else {
