			binary[y] = make([]int, effW)
			for x := 0; x < effW; x++ {
				if int(grays[y][x]) >= thresh {
					binary[y][x] = 1
				} else {
					binary[y][x] = 0
				}
			}
		}
	}
	// Pack into braille chars: each char covers 2x4 pixels
	chars := make([][]rune, rows)
	colors := make([][]color.RGBA, rows)
	for by := 0; by < rows; by++ {
		chars[by] = make([]rune, cols)
		colors[by] = make([]color.RGBA, cols)
		for bx := 0; bx < cols; bx++ {
			// Dots: bit0:(0,0),1:(0,1),2:(0,2),3:(1,0),4:(1,1),5:(1,2),6:(0,3),7:(1,3) relative to block top-left (bx*2, by*4)
			// Note: after flip, dots need mirroring? Instead of flipping binary matrix then packing, we pack then flip chars with dot mirroring? Easier: flip binary matrix first (with pixel mirroring), then pack? For flipX, mirror each row horizontally (reverse order)? But also need to mirror within each char? If we flip binary matrix horizontally (reverse columns), then pack, dots within chars will be mirrored correctly (since columns reversed). Similarly for vertical (reverse rows). Good. So apply flip to binary and colors before packing? But colors are per-char top-left, not per-pixel. For flip, colors should move with chars (like ascii). Easier: pack first, then flip chars (with dot mirroring for flip).
			// For now, pack without flip, then flip later with mirroring.
			x0 := bx * 2
			y0 := by * 4
			bits := 0
			if binary[y0+0][x0+0] == 1 {
				bits |= 1 << 0 // dot1
			}
			if binary[y0+1][x0+0] == 1 {
				bits |= 1 << 1 // dot2
			}
			if binary[y0+2][x0+0] == 1 {
				bits |= 1 << 2 // dot3
			}
			if binary[y0+0][x0+1] == 1 {
				bits |= 1 << 3 // dot4
			}
			if binary[y0+1][x0+1] == 1 {
				bits |= 1 << 4 // dot5
			}
			if binary[y0+2][x0+1] == 1 {
				bits |= 1 << 5 // dot6
			}
			if binary[y0+3][x0+0] == 1 {
				bits |= 1 << 6 // dot7
			}
			if binary[y0+3][x0+1] == 1 {
				bits |= 1 << 7 // dot8
