			// For grayscale, similarly invert gray? Likely yes (same as ascii). Good.
			// For fontcolor, no invert. Good.
			c := color.RGBAModel.Convert(resized.At(b.Min.X+x0, b.Min.Y+y0)).(color.RGBA)
			colors[by][bx] = c
		}
	}
	// Flip with dot mirroring
	if fv.FlipX {
		for by := 0; by < rows; by++ {
			// Reverse order and mirror each char horizontally (swap left/right columns: dot1<->dot4, dot2<->dot5, dot3<->dot6, dot7<->dot8)
			// Mirror function: bits 0<->3,1<->4,2<->5,6<->7
			for bx := 0; bx < cols; bx++ {
