			// Reverse
			for bx := 0; bx < cols/2; bx++ {
				chars[by][bx], chars[by][cols-1-bx] = chars[by][cols-1-bx], chars[by][bx]
				colors[by][bx], colors[by][cols-1-bx] = colors[by][cols-1-bx], colors[by][bx]
			}
		}
	}
	if fv.FlipY {
		for bx := 0; bx < cols; bx++ {
			for by := 0; by < rows; by++ {
				chars[by][bx] = mirrorBrailleY(chars[by][bx])
			}
		}
		for by := 0; by < rows/2; by++ {
			chars[by], chars[rows-1-by] = chars[rows-1-by], chars[by]
			colors[by], colors[rows-1-by] = colors[rows-1-by], colors[by]
		}
	}
	return chars, colors
}

func mirrorBrailleX(ch rune) rune {
	code := int(ch) - 0x2800
	b0 := (code >> 0) & 1
	b1 := (code >> 1) & 1
	b2 := (code >> 2) & 1
	b3 := (code >> 3) & 1
	b4 := (code >> 4) & 1
	b5 := (code >> 5) & 1
	b6 := (code >> 6) & 1
	b7 := (code >> 7) & 1
	// Swap: 0<->3,1<->4,2<->5,6<->7
	newCode := (b3 << 0) | (b4 << 1) | (b5 << 2) | (b0 << 3) | (b1 << 4) | (b2 << 5) | (b7 << 6) | (b6 << 7)
	return rune(0x2800 + newCode)
}
func mirrorBrailleY(ch rune) rune {
	code := int(ch) - 0x2800
	b0 := (code >> 0) & 1 // (0,0)
	b1 := (code >> 1) & 1 // (0,1)
	b2 := (code >> 2) & 1 // (0,2)
	b3 := (code >> 3) & 1 // (1,0)
	b4 := (code >> 4) & 1 // (1,1)
	b5 := (code >> 5) & 1 // (1,2)
	b6 := (code >> 6) & 1 // (0,3)
	b7 := (code >> 7) & 1 // (1,3)
	// Vertical flip: y0<->y3, y1<->y2
	// Left col: 0(0,0)<->6(0,3), 1(0,1)<->2(0,2)
	// Right col: 3(1,0)<->7(1,3), 4(1,1)<->5(1,2)
	newCode := (b6 << 0) | (b2 << 1) | (b1 << 2) | (b7 << 3) | (b5 << 4) | (b4 << 5) | (b0 << 6) | (b3 << 7)
	return rune(0x2800 + newCode)
}

func formatBrailleLines(chars [][]rune, colors [][]color.RGBA, fv *FlagValues, support int) string {
	useColor, mode := shouldUseColor(fv)
	var sb strings.Builder
	var fr, fg, fb int
	if mode == "fontcolor" {
		fr, fg, fb = fv.FontColor[0], fv.FontColor[1], fv.FontColor[2]
	}
	useBg := fv.ColorBg
	for y, row := range chars {
		for x, ch := range row {
			if !useColor {
				sb.WriteRune(ch)
			} else {
				var r, g, b int
				switch mode {
				case "color":
					c := colors[y][x]
					r, g, b = int(c.R), int(c.G), int(c.B)
					if fv.Negative {
						r, g, b = 255-r, 255-g, 255-b
					}
				case "grayscale":
					c := colors[y][x]
					gray := grayValue(c.R, c.G, c.B)
					if fv.Negative {
						gray = 255 - gray
					}
					r, g, b = int(gray), int(gray), int(gray)
				case "fontcolor":
					r, g, b = fr, fg, fb
				}
				sb.WriteString(formatColoredChar(ch, r, g, b, useBg, support))
			}
		}
