func srgbToLinear(c uint8) float64 {
	v := float64(c) / 255.0
	if v <= 0.04045 {
		return v / 12.92
	}
	return math.Pow((v+0.055)/1.055, 2.4)
}

func ditherFloydLinear(grays [][]uint8, w, h int) [][]int {
	// Convert to linear 0-255 float, Floyd-Steinberg with threshold 128, return binary
	img := make([][]float64, h)
	for y := 0; y < h; y++ {
		img[y] = make([]float64, w)
		for x := 0; x < w; x++ {
			img[y][x] = srgbToLinear(grays[y][x]) * 255.0
		}
	}
	out := make([][]int, h)
	for y := 0; y < h; y++ {
		out[y] = make([]int, w)
	}
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			old := img[y][x]
			var newVal float64
			if old >= 128 {
				newVal = 255
				out[y][x] = 1
			} else {
				newVal = 0
				out[y][x] = 0
			}
			err := old - newVal
			if x+1 < w {
				img[y][x+1] += err * 7 / 16
			}
			if y+1 < h {
				if x-1 >= 0 {
					img[y+1][x-1] += err * 3 / 16
				}
				img[y+1][x] += err * 5 / 16
				if x+1 < w {
					img[y+1][x+1] += err * 1 / 16
				}
			}
		}
	}
	return out
}

