func grayValue(r, g, b uint8) uint8 {
	// Go's color.GrayModel conversion: (19595*R + 38470*G + 7471*B + 1<<15) >> 16 >> 8, where R,G,B are 16-bit (x*257)
	R := uint32(r) * 257
	G := uint32(g) * 257
	B := uint32(b) * 257
	y := (19595*R + 38470*G + 7471*B + (1 << 15)) >> 16
	return uint8(y >> 8)
}

func resizeImage(src image.Image, newW, newH int) image.Image {
	// Bilinear with centered coordinates, clamp edges.
	// If newW==srcW && newH==srcH, return src directly (to preserve exact values, avoid float errors)
	b := src.Bounds()
	srcW := b.Dx()
	srcH := b.Dy()
	if newW == srcW && newH == srcH {
		return src
	}
	// Handle 0 dims? Will panic in original (index out of range). To replicate panic, try to create image with 0 size and access [0]? Actually image.NewRGBA with 0 size is valid (empty), but later ConvertToAsciiChars accesses [0] and panics.
	// Our code should also panic for 0 dims. Simplest: if newW<=0 || newH<=0, trigger panic by accessing empty slice.
	if newW <= 0 || newH <= 0 {
		var s []uint8
		_ = s[0] // panic: index out of range [0] with length 0
	}
	dst := image.NewRGBA(image.Rect(0, 0, newW, newH))
	xRatio := float64(srcW) / float64(newW)
	yRatio := float64(srcH) / float64(newH)
	for dy := 0; dy < newH; dy++ {
		srcY := (float64(dy)+0.5)*yRatio - 0.5
		y0 := int(math.Floor(srcY))
		y1 := y0 + 1
		wy := srcY - float64(y0)
		if y0 < 0 {
			y0 = 0
			y1 = 0
			wy = 0
		} else if y1 >= srcH {
			if y0 >= srcH {
				y0 = srcH - 1
				y1 = srcH - 1
				wy = 0
			} else {
				y1 = srcH - 1
				// wy stays? Actually if y1 clamped, wy should be? For edge, srcY beyond, clamp to edge (wy=0, use y0)?
				// Standard clamp: if srcY<0, use 0; if srcY>srcH-1, use srcH-1.
				// Our y0,y1,wy handling above is simplified. Better to clamp srcY first?
				// Let's do proper: if srcY<0, srcY=0; if srcY>srcH-1, srcY=srcH-1; then y0=floor, y1=min(y0+1,srcH-1), wy=srcY-y0
			}
		}
		// Recompute with clamping for correctness
		sy := (float64(dy)+0.5)*yRatio - 0.5
		if sy < 0 {
			sy = 0
		}
		if sy > float64(srcH-1) {
			sy = float64(srcH - 1)
		}
		y0 = int(math.Floor(sy))
		y1 = y0 + 1
		if y1 >= srcH {
			y1 = srcH - 1
		}
		wy = sy - float64(y0)
		for dx := 0; dx < newW; dx++ {
			sx := (float64(dx)+0.5)*xRatio - 0.5
			if sx < 0 {
				sx = 0
			}
			if sx > float64(srcW-1) {
				sx = float64(srcW - 1)
			}
			x0 := int(math.Floor(sx))
			x1 := x0 + 1
			if x1 >= srcW {
				x1 = srcW - 1
			}
			wx := sx - float64(x0)
			// Sample 4 pixels
			c00 := color.RGBAModel.Convert(src.At(b.Min.X+x0, b.Min.Y+y0)).(color.RGBA)
			c10 := color.RGBAModel.Convert(src.At(b.Min.X+x1, b.Min.Y+y0)).(color.RGBA)
			c01 := color.RGBAModel.Convert(src.At(b.Min.X+x0, b.Min.Y+y1)).(color.RGBA)
			c11 := color.RGBAModel.Convert(src.At(b.Min.X+x1, b.Min.Y+y1)).(color.RGBA)
			// Bilinear interpolate each channel
			r := float64(c00.R)*(1-wx)*(1-wy) + float64(c10.R)*wx*(1-wy) + float64(c01.R)*(1-wx)*wy + float64(c11.R)*wx*wy
			g := float64(c00.G)*(1-wx)*(1-wy) + float64(c10.G)*wx*(1-wy) + float64(c01.G)*(1-wx)*wy + float64(c11.G)*wx*wy
			bb := float64(c00.B)*(1-wx)*(1-wy) + float64(c10.B)*wx*(1-wy) + float64(c01.B)*(1-wx)*wy + float64(c11.B)*wx*wy
			a := float64(c00.A)*(1-wx)*(1-wy) + float64(c10.A)*wx*(1-wy) + float64(c01.A)*(1-wx)*wy + float64(c11.A)*wx*wy
			dst.SetRGBA(dx, dy, color.RGBA{uint8(math.Round(r)), uint8(math.Round(g)), uint8(math.Round(bb)), uint8(math.Round(a))})
		}
	}
	return dst
}

func getCharMap(fv *FlagValues) string {
	if fv.Braille {
		return "" // not used
	}
	if fv.Map != "" {
		return fv.Map
	}
	if fv.Complex {
		return complexMap
	}
	return simpleMap
}

func mapGrayToChar(gray uint8, charMap string, negative bool) rune {
	n := len([]rune(charMap)) // use rune count? For ASCII maps, same as byte len. For custom maps with unicode? Possibly. Use rune.
	runes := []rune(charMap)
	// idx = gray * n / 255, capped to n-1
	idx := int(gray) * n / 255
	if idx >= n {
		idx = n - 1
	}
	if negative {
		idx = n - 1 - idx
	}
	return runes[idx]
}

// 8-bit color mapping
var cubeVals = []int{0, 95, 135, 175, 215, 255}

