func closestCubeVal(v int) int {
	// Thresholds: <48=>0, <115=>95, <155=>135, <195=>175, <235=>215, else 255
	// Upper on tie (v==115 =>135, v==195=>215, etc.)
	if v < 48 {
		return 0
	} else if v < 115 {
		return 95
	} else if v < 155 {
		return 135
	} else if v < 195 {
		return 175
	} else if v < 235 {
		return 215
	} else {
		return 255
	}
}
func indexOfCubeVal(v int) int {
	for i, cv := range cubeVals {
		if cv == v {
			return i
		}
	}
	return 0
}

func shouldUseColor(fv *FlagValues) (useColor bool, colorMode string) {
	// Returns whether to colorize, and which mode: "color", "grayscale", "fontcolor", or "" for plain
	// Precedence: --color overrides --grayscale and --font-color; --grayscale overrides --font-color.
	// --font-color with white (255,255,255) or unset means no color (plain), unless --color/--grayscale present.
	// --color-bg alone (without color/grayscale/fontcolor non-white) means no color.
	if fv.Color {
		return true, "color"
	}
	if fv.Grayscale {
		return true, "grayscale"
	}
	if len(fv.FontColor) == 3 {
		r, g, b := fv.FontColor[0], fv.FontColor[1], fv.FontColor[2]
		if r == 255 && g == 255 && b == 255 {
			return false, ""
		}
		return true, "fontcolor"
	}
	// FontColor unset (len 0) means default white => no color
	return false, ""
}

func needsColorSupport(fv *FlagValues) bool {
	use, _ := shouldUseColor(fv)
	return use
}

func formatColoredChar(ch rune, r, g, b int, useBg bool, support int) string {
	var prefix string
	if support == 24 {
		if useBg {
			prefix = fmt.Sprintf("\x1b[48;2;%d;%d;%dm", r, g, b)
		} else {
			prefix = fmt.Sprintf("\x1b[38;2;%d;%d;%dm", r, g, b)
		}
	} else { // 8-bit
		code := rgbTo8bit(r, g, b)
		if useBg {
			prefix = fmt.Sprintf("\x1b[48;5;%dm", code)
		} else {
			prefix = fmt.Sprintf("\x1b[38;5;%dm", code)
		}
	}
	return prefix + string(ch) + "\x1b[0m"
}

