func formatAsciiLines(lines []string, colors [][]color.RGBA, fv *FlagValues, support int) string {
	useColor, mode := shouldUseColor(fv)
	if !useColor {
		// Plain: join lines with \n, each line + \n (including last? Yes, stdout has trailing \n after each line, including last. File has no trailing \n after last? For stdout, yes. For save-txt file, no trailing after last. This function is for stdout (with trailing). For file, use different (without trailing).
		var sb strings.Builder
		for _, line := range lines {
			sb.WriteString(line)
			sb.WriteString("\n")
		}
		return sb.String()
	}
	// Color: for each char, format with ANSI
	var sb strings.Builder
	// Determine font-color for fontcolor mode
	var fr, fg, fb int
	if mode == "fontcolor" {
		fr, fg, fb = fv.FontColor[0], fv.FontColor[1], fv.FontColor[2]
	}
	useBg := fv.ColorBg
	for y, line := range lines {
		runes := []rune(line)
		for x, ch := range runes {
			var r, g, b int
			switch mode {
			case "color":
				c := colors[y][x]
				r, g, b = int(c.R), int(c.G), int(c.B)
				if fv.Negative {
					r, g, b = 255-r, 255-g, 255-b
				}
			case "grayscale":
				c := colors[y][x]
				gray := grayValue(c.R, c.G, c.B)
				if fv.Negative {
					gray = 255 - gray
				}
				r, g, b = int(gray), int(gray), int(gray)
			case "fontcolor":
				r, g, b = fr, fg, fb
				// Negative does NOT invert font-color (as observed)
			}
			sb.WriteString(formatColoredChar(ch, r, g, b, useBg, support))
		}
		sb.WriteString("\n")
	}
	return sb.String()
}

func formatAsciiForFile(lines []string) string {
	// Join with \n, no trailing \n after last (as observed: file has no trailing newline)
	return strings.Join(lines, "\n")
}

