func convertToBraille(img image.Image, fv *FlagValues, cols, rows int) ([][]rune, [][]color.RGBA) {
	// Effective pixels: cols*2 x rows*4
	effW := cols * 2
	effH := rows * 4
	if effW <= 0 || effH <= 0 {
		var s []uint8
		_ = s[0]
	}
