	// For dither, need to dither grayscale matrix (in linear space? For now, implement Floyd in sRGB? Or linear? Let's implement linear sRGB EOTF + Floyd float to match observed approximately.)
	// For threshold (no dither), threshold each pixel: pixel >= thresh? (with thresh0 bug: thresh 0 treated as 128)
	thresh := fv.Threshold
	if thresh == 0 {
		thresh = 128
	}
	// Build gray matrix
	grays := make([][]uint8, effH)
