func mirrorBrailleX(ch rune) rune {
	code := int(ch) - 0x2800
	b0 := (code >> 0) & 1
	b1 := (code >> 1) & 1
	b2 := (code >> 2) & 1
	b3 := (code >> 3) & 1
	b4 := (code >> 4) & 1
	b5 := (code >> 5) & 1
	b6 := (code >> 6) & 1
	b7 := (code >> 7) & 1
	// Swap: 0<->3,1<->4,2<->5,6<->7
	newCode := (b3 << 0) | (b4 << 1) | (b5 << 2) | (b0 << 3) | (b1 << 4) | (b2 << 5) | (b7 << 6) | (b6 << 7)
	return rune(0x2800 + newCode)
}
func mirrorBrailleY(ch rune) rune {
	code := int(ch) - 0x2800
	b0 := (code >> 0) & 1 // (0,0)
	b1 := (code >> 1) & 1 // (0,1)
	b2 := (code >> 2) & 1 // (0,2)
	b3 := (code >> 3) & 1 // (1,0)
	b4 := (code >> 4) & 1 // (1,1)
	b5 := (code >> 5) & 1 // (1,2)
	b6 := (code >> 6) & 1 // (0,3)
	b7 := (code >> 7) & 1 // (1,3)
	// Vertical flip: y0<->y3, y1<->y2
	// Left col: 0(0,0)<->6(0,3), 1(0,1)<->2(0,2)
	// Right col: 3(1,0)<->7(1,3), 4(1,1)<->5(1,2)
	newCode := (b6 << 0) | (b2 << 1) | (b1 << 2) | (b7 << 3) | (b5 << 4) | (b4 << 5) | (b0 << 6) | (b3 << 7)
	return rune(0x2800 + newCode)
}

func formatBrailleLines(chars [][]rune, colors [][]color.RGBA, fv *FlagValues, support int) string {
	useColor, mode := shouldUseColor(fv)
	var sb strings.Builder
	var fr, fg, fb int
	if mode == "fontcolor" {
		fr, fg, fb = fv.FontColor[0], fv.FontColor[1], fv.FontColor[2]
	}
	useBg := fv.ColorBg
	for y, row := range chars {
		for x, ch := range row {
			if !useColor {
				sb.WriteRune(ch)
			} else {
				var r, g, b int
				switch mode {
				case "color":
					c := colors[y][x]
					r, g, b = int(c.R), int(c.G), int(c.B)
					if fv.Negative {
						r, g, b = 255-r, 255-g, 255-b
					}
				case "grayscale":
					c := colors[y][x]
					gray := grayValue(c.R, c.G, c.B)
					if fv.Negative {
						gray = 255 - gray
					}
					r, g, b = int(gray), int(gray), int(gray)
				case "fontcolor":
					r, g, b = fr, fg, fb
				}
				sb.WriteString(formatColoredChar(ch, r, g, b, useBg, support))
			}
		}
		sb.WriteString("\n")
	}
	return sb.String()
}

func formatBrailleForFile(chars [][]rune) string {
	var lines []string
	for _, row := range chars {
		lines = append(lines, string(row))
	}
	return strings.Join(lines, "\n")
}

func srgbToLinear(c uint8) float64 {
	v := float64(c) / 255.0
	if v <= 0.04045 {
		return v / 12.92
	}
	return math.Pow((v+0.055)/1.055, 2.4)
}

func ditherFloydLinear(grays [][]uint8, w, h int) [][]int {
	// Convert to linear 0-255 float, Floyd-Steinberg with threshold 128, return binary
	img := make([][]float64, h)
	for y := 0; y < h; y++ {
		img[y] = make([]float64, w)
		for x := 0; x < w; x++ {
			img[y][x] = srgbToLinear(grays[y][x]) * 255.0
		}
	}
	out := make([][]int, h)
	for y := 0; y < h; y++ {
		out[y] = make([]int, w)
	}
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			old := img[y][x]
			var newVal float64
			if old >= 128 {
				newVal = 255
				out[y][x] = 1
			} else {
				newVal = 0
				out[y][x] = 0
			}
			err := old - newVal
			if x+1 < w {
				img[y][x+1] += err * 7 / 16
			}
			if y+1 < h {
				if x-1 >= 0 {
					img[y+1][x-1] += err * 3 / 16
				}
				img[y+1][x] += err * 5 / 16
				if x+1 < w {
					img[y+1][x+1] += err * 1 / 16
				}
			}
		}
	}
	return out
}

