	"errors"
	"image"
	"image/color"
	"unsafe"
)

func decodeWEBPCGO(data []byte) (image.Image, string, error) {
	if len(data) < 12 {
		return nil, "", errors.New("riff: short chunk data")
	}
	if string(data[0:4]) != "RIFF" {
		return nil, "", errors.New("image: unknown format")
	}
	if string(data[8:12]) != "WEBP" {
		return nil, "", errors.New("image: unknown format")
	}
	if len(data) < 20 {
		return nil, "", errors.New("riff: short chunk data")
	}
	chunk := string(data[12:16])
	if chunk != "VP8 " && chunk != "VP8L" && chunk != "VP8X" {
		return nil, "", errors.New("riff: short chunk data")
	}
	// Try libwebp decode
	var w, h C.int
	out := C.WebPDecodeRGBA((*C.uchar)(unsafe.Pointer(&data[0])), C.ulong(len(data)), &w, &h)
	if out == nil {
		// Decode failed: what error to return to match original's x/image/webp errors for invalid WEBP?
		// Original for invalid WEBP (e.g., truncated VP8 data) might give "webp: ..." or "riff: ..."? Our fake WEBP (16 bytes, header only, no valid VP8 data) gave "riff: short chunk data" (since len<20? Actually fake was 16 bytes, len<20, so we already returned short before libwebp. Good.
		// For longer invalid WEBP (e.g., 1000 bytes of As with valid header? Actually As don't have valid header, already returned bad? Hmm.
		// For valid header but invalid VP8 data (e.g., VP8 chunk with garbage), libwebp fails (returns nil). What would original's x/image/webp return? Possibly "webp: invalid ..."? Need to test original with invalid VP8 data (valid header, garbage payload) to see error. Since we lost original, cannot test. For now, return "image: unknown format"? Or "webp: ..."? Let's return "image: unknown format" for libwebp failures (to match generic decode failure?).
		// Actually for WEBP with valid header but corrupt payload, original likely returns "webp: ..." (from webp decoder, not riff). Our stub should return similar to avoid mismatch? But without original to test, hard.
		// For now, return "image: unknown format" for libwebp failures (conservative?).
		return nil, "", errors.New("image: unknown format")
	}
	defer C.WebPFree(unsafe.Pointer(out))
	width, height := int(w), int(h)
	if width <= 0 || height <= 0 {
		return nil, "", errors.New("image: unknown format")
	}
	// Copy pixels (RGBA, stride width*4)
	n := width * height * 4
	pixels := (*[1 << 30]byte)(unsafe.Pointer(out))[:n:n]
	img := image.NewRGBA(image.Rect(0, 0, width, height))
	copy(img.Pix, pixels)
	return img, "webp", nil
}
