package main
/*
#cgo LDFLAGS: -L/tmp/mylib -lwebp
#include <stdlib.h>
extern unsigned long WebPEncodeLosslessRGBA(const unsigned char* data, int width, int height, int stride, unsigned char** output);
extern void WebPFree(void* ptr);
*/
import "C"
import (
	"fmt"
	"os"
	"unsafe"
)
func main() {
	// 2x2 image: red, green / blue, white (same as color2)
	w,h:=2,2
	pixels:=[]byte{
		255,0,0,255, 0,255,0,255,
		0,0,255,255, 255,255,255,255,
	}
	var out *C.uchar
	size:=C.WebPEncodeLosslessRGBA((*C.uchar)(unsafe.Pointer(&pixels[0])), C.int(w), C.int(h), C.int(w*4), &out)
	if size==0 {
		fmt.Println("encode failed")
		return
	}
	defer C.WebPFree(unsafe.Pointer(out))
	data:=C.GoBytes(unsafe.Pointer(out), C.int(size))
	os.WriteFile("/tmp/test_lossless.webp", data, 0644)
	fmt.Printf("wrote lossless %d bytes\n", len(data))
	// 4x4 grad?
	pixels2:=make([]byte,4*4*4)
	vals:=[]byte{0,85,170,255}
	for y:=0;y<4;y++{
		for x:=0;x<4;x++{
			v:=vals[x]
			idx:=(y*4+x)*4
			pixels2[idx]=v
			pixels2[idx+1]=v
			pixels2[idx+2]=v
			pixels2[idx+3]=255
		}
	}
	var out2 *C.uchar
	size2:=C.WebPEncodeLosslessRGBA((*C.uchar)(unsafe.Pointer(&pixels2[0])), 4,4,16, &out2)
	if size2==0 {
		fmt.Println("encode2 failed")
		return
	}
	defer C.WebPFree(unsafe.Pointer(out2))
	data2:=C.GoBytes(unsafe.Pointer(out2), C.int(size2))
	os.WriteFile("/tmp/grad4_lossless.webp", data2, 0644)
	fmt.Printf("wrote grad4 lossless %d bytes\n", len(data2))
}
GO
